// API @jinx-ui/react восстановлен по типовым соглашениям библиотеки — сверьте имена компонентов и сигнатуры onChange с документацией пакета.
import { FormEvent, useState } from 'react';
import { Button, Form, FormField, Input, Select, Stack, Switch } from '@jinx-ui/react';

type Language = 'ru' | 'en';

type ProfileSettings = {
  name: string;
  language: Language;
  emailNotifications: boolean;
};

type ProfileSettingsFormProps = {
  initialSettings?: Partial<ProfileSettings>;
  onSave: (settings: ProfileSettings) => void;
};

const LANGUAGE_OPTIONS: ReadonlyArray<{ value: Language; label: string }> = [
  { value: 'ru', label: 'Русский' },
  { value: 'en', label: 'English' },
];

export default function ProfileSettingsForm({ initialSettings, onSave }: ProfileSettingsFormProps) {
  const [name, setName] = useState(initialSettings?.name ?? '');
  const [language, setLanguage] = useState<Language>(initialSettings?.language ?? 'ru');
  const [emailNotifications, setEmailNotifications] = useState(initialSettings?.emailNotifications ?? false);

  const trimmedName = name.trim();

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    onSave({ name: trimmedName, language, emailNotifications });
  };

  return (
    <Form onSubmit={handleSubmit}>
      <Stack direction="column" style={{ gap: 'var(--jx-space-4)' }}>
        <FormField label="Имя" htmlFor="profile-name">
          <Input
            id="profile-name"
            name="name"
            value={name}
            placeholder="Введите имя"
            onChange={(event) => setName(event.target.value)}
          />
        </FormField>

        <FormField label="Язык интерфейса" htmlFor="profile-language">
          <Select
            id="profile-language"
            name="language"
            value={language}
            options={LANGUAGE_OPTIONS}
            onChange={(value: Language) => setLanguage(value)}
          />
        </FormField>

        <Switch
          id="profile-email-notifications"
          name="emailNotifications"
          label="Уведомления на почту"
          checked={emailNotifications}
          onChange={(checked: boolean) => setEmailNotifications(checked)}
        />

        <Button type="submit" variant="primary" disabled={trimmedName.length === 0}>
          Сохранить
        </Button>
      </Stack>
    </Form>
  );
}

